import { createLedgerReport, LedgerEntry } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function rangeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    assert(error instanceof RangeError, `${message}: wrong error type`);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const source: LedgerEntry[] = [
  { id: "OLD", account: "A", day: 1, delta: 10 },
  { id: "Z", account: "B", day: 3, delta: 7 },
  { id: "SAME", account: "A", day: 2, delta: 2 },
  { id: "SAME", account: "A", day: 2, delta: 3 },
  { id: "AFTER", account: "A", day: 5, delta: 100 },
  { id: "MID", account: "C", day: 3, delta: 9 },
  { id: "A", account: "A", day: 3, delta: -4 },
];
const snapshot = JSON.stringify(source);
const report = createLedgerReport(" A, B, A, , C ", 2, 3, source);
equal(report.accounts, ["A", "B", "C"], "accounts are normalized in first-occurrence order");
equal(report.openingBalances, { A: 10, B: 0, C: 0 }, "opening balances");
equal(report.closingBalances, { A: 11, B: 7, C: 9 }, "closing balances");
equal(report.entries.map(e => `${e.day}:${e.id}:${e.delta}`), [
  "2:SAME:2", "2:SAME:3", "3:A:-4", "3:MID:9", "3:Z:7",
], "entries are sorted stably");
assert(JSON.stringify(source) === snapshot, "source was mutated");
assert(report.entries[0] !== source[2], "returned entry aliases source");
(report.entries[0] as { delta: number }).delta = 999;
assert(source[2].delta === 2, "mutating a returned entry changed source");

const empty = createLedgerReport(" , , ", 0, 0, [{ id: "X", account: "A", day: 0, delta: 1 }]);
equal(empty.accounts, [], "empty account selection");
equal(empty.openingBalances, {}, "empty opening balances");
equal(empty.closingBalances, {}, "empty closing balances");
equal(empty.entries, [], "empty selected entries");

rangeError(() => createLedgerReport("bad", 0, 1, []), "invalid selected account");
rangeError(() => createLedgerReport("A", 2, 1, []), "reversed range");
rangeError(() => createLedgerReport("A", 0.5, 1, []), "noninteger start");
rangeError(() => createLedgerReport("A", 0, 1.5, []), "noninteger end");
rangeError(() => createLedgerReport("", 0, 1, [{ id: "bad", account: "A", day: 0, delta: 1 }]), "invalid unselected ID");
rangeError(() => createLedgerReport("A", 0, 1, [{ id: "X", account: "OTHER", day: 0.1, delta: 1 }]), "invalid unselected day");
rangeError(() => createLedgerReport("A", 0, 1, [{ id: "X", account: "OTHER", day: 0, delta: Infinity }]), "invalid unselected delta");
rangeError(() => createLedgerReport("A", 0, 1, [{ id: "X", account: "bad", day: 0, delta: 1 }]), "invalid unselected account");

